import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class SplitITupVariant4 {
    public static void main(String[] args) {
        List<Integer> openIndices = new ArrayList<>();
        List<Integer> closeIndices = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);
        int num = scanner.nextInt();
        String strInput = scanner.next();

        for (int i = 0; i < num; i++) {
            if (strInput.charAt(i) == '(') {
                openIndices.add(i);
            } else if (strInput.charAt(i) == ')') {
                closeIndices.add(i);
            }
        }

        int wordCount = 0;
        for (String segment : extractSegments(strInput, openIndices, closeIndices)) {
            String[] parts = segment.split("_");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    wordCount++;
                }
            }
        }

        int maxWordLen = 0;
        openIndices.add(strInput.length());
        closeIndices.add(0, 0);
        int startIdx = strInput.charAt(0) == '(' ? 1 : 0;

        for (int i = startIdx; i < closeIndices.size(); i++) {
            String segment;
            if (strInput.charAt(closeIndices.get(i)) == ')') {
                segment = strInput.substring(closeIndices.get(i) + 1, openIndices.get(i));
            } else {
                segment = strInput.substring(closeIndices.get(i), openIndices.get(i));
            }
            String[] parts = segment.split("_");
            for (String part : parts) {
                if (part.length() > maxWordLen && !part.contains("(") && !part.contains(")")) {
                    maxWordLen = part.length();
                }
            }
        }
        System.out.println(maxWordLen + " " + wordCount);
    }

    private static List<String> extractSegments(String s, List<Integer> starts, List<Integer> ends) {
        List<String> segments = new ArrayList<>();
        for (int i = 0; i < starts.size(); i++) {
            segments.add(s.substring(starts.get(i) + 1, ends.get(i)));
        }
        return segments;
    }
}
